async page=>{const ctx=await page.context().browser().newContext({viewport:{width:390,height:844},hasTouch:true,reducedMotion:'reduce'});const p=await ctx.newPage();const out=[];for(const route of ['/case-studies/optro','/about','/case-studies/simon-schuster','/case-studies/weaponized-innocence','/case-studies/seek-truth','/']){await p.goto('https://micahhoang.com'+route,{waitUntil:'domcontentloaded'});await p.waitForTimeout(1300);await p.addStyleTag({path:'output/playwright/mobile-target-fixes-2026-10-30/mobile.css'});await p.addStyleTag({path:'output/playwright/mobile-target-fixes-2026-10-30/carousel.css'});await p.evaluate(()=>{document.querySelectorAll('button[aria-label="Previous slide"],button[aria-label="Next slide"]').forEach(e=>e.classList.add('mh-carousel-arrow'));document.querySelectorAll('[aria-label="Slide navigation"]').forEach(e=>e.classList.add('mh-carousel-dots'));document.querySelectorAll('button[aria-label^="Go to slide"]').forEach(e=>{e.style.setProperty('--mh-dot-width',e.style.width);e.style.setProperty('--mh-dot-color',e.style.background);e.classList.add('mh-carousel-dot')})});for(const width of [320,390,430]){await p.setViewportSize({width,height:844});out.push(await p.evaluate(()=>{const vis=e=>{const r=e.getBoundingClientRect();return r.width&&r.height&&getComputedStyle(e).visibility!=='hidden'};const els=[...document.querySelectorAll('[data-framer-name="Section CTA"] a,button[aria-label*="slide"],p[data-styles-preset="EoCREtojJ"] > a')].filter(vis);return{path:location.pathname,width:innerWidth,overflow:document.documentElement.scrollWidth>innerWidth,targets:els.map(e=>({text:(e.getAttribute('aria-label')||e.textContent).replace(/\s+/g,' ').trim(),w:e.getBoundingClientRect().width,h:e.getBoundingClientRect().height,fonts:[...new Set([e,...e.querySelectorAll('*')].filter(x=>!x.children.length).map(x=>getComputedStyle(x).fontSize+' '+getComputedStyle(x).fontWeight+' '+getComputedStyle(x).fontFamily))]}))}}));}await p.setViewportSize({width:390,height:844});const target=route.endsWith('optro')?p.locator('[data-framer-name="Section CTA"]'):route==='/about'?p.locator('p[data-styles-preset="EoCREtojJ"]:has(a)').first():p.locator('button[aria-label="Next slide"]').first();if(await target.count()){await target.scrollIntoViewIfNeeded();await p.waitForTimeout(500);await p.screenshot({path:'output/playwright/mobile-target-fixes-2026-10-30/proto-'+(route.split('/').pop()||'home')+'.png'});}}await ctx.close();return out;}
